// Text-plane helpers (Convert nodes / Get Save Value)
static inline std::string flowNumText(float v) {
  char b[32];
  snprintf(b, sizeof(b), "%g", (double)v);
  return std::string(b);
}
static inline std::string flowPosText(float x, float y, float z) {
  char b[64];
  snprintf(b, sizeof(b), "(%g, %g, %g)", (double)x, (double)y, (double)z);
  return std::string(b);
}

// Display Text: copy a runtime string into its slot's buffer
// (silently truncated - the slot is a fixed DYN_TEXT_LEN).
static inline void flowSetDynText(ScriptContext& ctx, int slot,
                                  const std::string& s) {
  if (!ctx.dynTextBuf || slot < 0 || slot >= ctx.dynTextCount) return;
  char* dst = ctx.dynTextBuf + slot * ctx.dynTextLen;
  int n = (int)s.size();
  if (n > ctx.dynTextLen - 1) n = ctx.dynTextLen - 1;
  for (int i = 0; i < n; ++i) dst[i] = s[i];
  dst[n] = '\0';
}

// Graph events (Send Event / On Event), one game-global namespace:
// power-on
static unsigned char flowEvtCur[1] = {};
static float flowEvtCurVal[1] = {};
static unsigned char flowEvtNext[1] = {};
static float flowEvtNextVal[1] = {};

// The bus. Registered before every graph script, so `cur` is
// already this frame's mail by the time any receiver looks.
class FlowEventBus : public Script {
 public:
  void update(ScriptContext& ctx) override {
    // Halted at a breakpoint: freeze the mail too, or an
    // event sent just before the stop would be dropped
    // while the author was looking at it.
    if (livedbg::halted()) return;
    if (ctx.sceneGeneration != generation_) {
      // A scene (re)load must not deliver the old scene's mail.
      generation_ = ctx.sceneGeneration;
      for (int i = 0; i < 1; ++i) {
        flowEvtCur[i] = flowEvtNext[i] = 0;
        flowEvtCurVal[i] = flowEvtNextVal[i] = 0.0F;
      }
      return;
    }
    for (int i = 0; i < 1; ++i) {
      flowEvtCur[i] = flowEvtNext[i];
      flowEvtCurVal[i] = flowEvtNextVal[i];
      flowEvtNext[i] = 0;
    }
  }

 private:
  unsigned int generation_ = 0;
};

// World Facts (docs/world-facts.md): the declared state of
// the game world. One float array for every scalar fact, one
// for positions; a computed fact has no slot because it IS a
// query. factWrite() is the only door in - it exists so the
// Live Debugger can record WHO changed a fact, and folds to a
// plain store when the debugger is off.
float factNum[8] = {0.0F, 0.0F, 0.0F, 0.0F, 0.0F, 0.0F, 0.0F, 0.0F};
float factPos[1][3] = {{0.0F, 0.0F, 0.0F}};

static bool g_factProfileDirty = false;
static const unsigned char FACT_NUM_PROFILE[8] = {0, 0, 0, 0, 0, 0, 0, 1};
static inline void factWrite(int slot, float v, int src) {
  if (factNum[slot] != v && FACT_NUM_PROFILE[slot])
    g_factProfileDirty = true;
  if (factNum[slot] != v) livedbg::factWrite(slot, v, src);
  factNum[slot] = v;
}
static inline void factWritePos(int slot, float x, float y,
                                float z, int src) {
  (void)0;  // positions never ride the profile file
  if (factPos[slot][0] != x || factPos[slot][1] != y ||
      factPos[slot][2] != z)
    livedbg::factWritePos(slot, x, y, z, src);
  factPos[slot][0] = x;
  factPos[slot][1] = y;
  factPos[slot][2] = z;
}
static const char* const factEnum1[3] = {"Broken", "Powered", "Overloaded"};  // world.power.state
static inline std::string flowEnumText(float v,
                                       const char* const* opts,
                                       int count) {
  const long i = lroundf(v);
  if (i < 0 || i >= count) return std::to_string(i);
  return std::string(opts[i]);
}

void factResetAll() {
  for (int i = 0; i < FACT_NUM_COUNT; ++i)
    factNum[i] = FACT_NUM_DEFAULT[i];
  for (int i = 0; i < FACT_POS_COUNT; ++i)
    for (int a = 0; a < 3; ++a)
      factPos[i][a] = FACT_POS_DEFAULT[i][a];
}

void factResetScene() {
  for (int i = 0; i < FACT_NUM_COUNT; ++i)
    if (FACT_NUM_SCENE[i]) factNum[i] = FACT_NUM_DEFAULT[i];
  for (int i = 0; i < FACT_POS_COUNT; ++i)
    if (FACT_POS_SCENE[i])
      for (int a = 0; a < 3; ++a)
        factPos[i][a] = FACT_POS_DEFAULT[i][a];
}

int factSaveCapture(FactSaveRow* out, int max) {
  int n = 0;
  if (n < max) {  // world.generator.parts
    out[n].id = 1516829334u;
    out[n].v[0] = factNum[0];
    out[n].v[1] = 0.0F;
    out[n].v[2] = 0.0F;
    ++n;
  }
  if (n < max) {  // world.power.state
    out[n].id = 1500051715u;
    out[n].v[0] = factNum[1];
    out[n].v[1] = 0.0F;
    out[n].v[2] = 0.0F;
    ++n;
  }
  if (n < max) {  // world.power.load
    out[n].id = 1483274096u;
    out[n].v[0] = factNum[2];
    out[n].v[1] = 0.0F;
    out[n].v[2] = 0.0F;
    ++n;
  }
  if (n < max) {  // characters.marta.trust
    out[n].id = 1583939810u;
    out[n].v[0] = factNum[4];
    out[n].v[1] = 0.0F;
    out[n].v[2] = 0.0F;
    ++n;
  }
  if (n < max) {  // characters.marta.rescued
    out[n].id = 1567162191u;
    out[n].v[0] = factNum[5];
    out[n].v[1] = 0.0F;
    out[n].v[2] = 0.0F;
    ++n;
  }
  if (n < max) {  // player.hasBasementKey
    out[n].id = 1667827905u;
    out[n].v[0] = factNum[6];
    out[n].v[1] = 0.0F;
    out[n].v[2] = 0.0F;
    ++n;
  }
  if (n < max) {  // player.lastCheckpoint
    out[n].id = 1651050286u;
    out[n].v[0] = factPos[0][0];
    out[n].v[1] = factPos[0][1];
    out[n].v[2] = factPos[0][2];
    ++n;
  }
  return n;
}

void factSaveRestore(const FactSaveRow* rows, int count) {
  for (int i = 0; i < count; ++i) {
    switch (rows[i].id) {
      case 1516829334u:  // world.generator.parts
        factNum[0] = rows[i].v[0];
        break;
      case 1500051715u:  // world.power.state
        factNum[1] = rows[i].v[0];
        break;
      case 1483274096u:  // world.power.load
        factNum[2] = rows[i].v[0];
        break;
      case 1583939810u:  // characters.marta.trust
        factNum[4] = rows[i].v[0];
        break;
      case 1567162191u:  // characters.marta.rescued
        factNum[5] = rows[i].v[0];
        break;
      case 1667827905u:  // player.hasBasementKey
        factNum[6] = rows[i].v[0];
        break;
      case 1651050286u:  // player.lastCheckpoint
        factPos[0][0] = rows[i].v[0];
        factPos[0][1] = rows[i].v[1];
        factPos[0][2] = rows[i].v[2];
        break;
      default: break;  // a fact this build no longer has
    }
  }
}

