bool factProfileDirty() {
  const bool d = g_factProfileDirty;
  g_factProfileDirty = false;
  return d;
}

// Named conditions (Tools > World Facts > Queries).
// Forward-declared as a block so one query may name
// another whatever order they were authored in; a query
// that takes part in a cycle is emitted as false.
static bool factQuery0();  // GeneratorReady
static bool factQuery1();  // MartaIsAlly
static bool factQuery2();  // CanEnterBasement
static bool factQuery0() {  // "GeneratorReady"
  return ((factNum[0]) >= (3.0F));
}
static bool factQuery1() {  // "MartaIsAlly"
  return ((fabsf((factNum[5]) - (1.0F)) <= 1e-4F) && ((factNum[4]) >= (5.0F)));
}
static bool factQuery2() {  // "CanEnterBasement"
  return ((fabsf((factNum[6]) - (1.0F)) <= 1e-4F) && ((fabsf((factNum[1]) - (1.0F)) <= 1e-4F) || factQuery1()));
}

// Fact rules (Tools > World Facts > Rules): the
// reactive half. Registered after the event bus and
// before every graph script, so a fact a rule writes is
// already there by the time a graph looks - and an event
// a rule sends rides the next frame's mail like any
// other.
class WorldFactRules : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (livedbg::halted()) return;
    if (ctx.sceneGeneration != generation_) {
      generation_ = ctx.sceneGeneration;
      factResetScene();
      // Re-arm the edge latches: entering a level must
      // re-fire what that level's state already implies.
      // `spent_` is deliberately NOT cleared - 'once per
      // run' means the run, not the scene.
      for (int i = 0; i < FACT_RULE_COUNT; ++i)
        was_[i] = false;
      return;
    }
    for (int pass = 0; pass < FACT_RULE_PASSES; ++pass) {
      bool changed = false;
      {  // rule "PowerRestored"
        const bool c = factQuery0();
        const bool fire = c && !was_[0];
        was_[0] = c;
        if (fire) {
          spent_[0] = true;
          factWrite(1, 1.0F, -2);
          flowEvtNext[0] = 1;
          flowEvtNextVal[0] = 0.0F;
          changed = true;
        }
      }
      {  // rule "OverloadTrips"
        const bool c = ((fabsf((factNum[1]) - (1.0F)) <= 1e-4F) && ((factNum[2]) > (0.8F)));
        const bool fire = c && !was_[1];
        was_[1] = c;
        if (fire) {
          spent_[1] = true;
          factWrite(1, 2.0F, -3);
          changed = true;
        }
      }
      {  // rule "PowerSettles"
        const bool c = ((fabsf((factNum[1]) - (2.0F)) <= 1e-4F) && ((factNum[2]) <= (0.1F)));
        const bool fire = c && !was_[2];
        was_[2] = c;
        if (fire) {
          spent_[2] = true;
          factWrite(1, 1.0F, -4);
          changed = true;
        }
      }
      {  // rule "AlarmWhileOverloaded"
        const bool c = (fabsf((factNum[1]) - (2.0F)) <= 1e-4F);
        const bool fire = c && pass == 0;
        was_[3] = c;
        if (fire) {
          spent_[3] = true;
          factWrite(3, 1.0F, -5);
          changed = true;
        }
      }
      {  // rule "RescueEarnsTrust"
        const bool c = (fabsf((factNum[5]) - (1.0F)) <= 1e-4F);
        const bool fire = c && !was_[4] && !spent_[4];
        was_[4] = c;
        if (fire) {
          spent_[4] = true;
          factWrite(4, factNum[4] + 5.0F, -6);
          changed = true;
        }
      }
      if (!changed) break;
    }
  }

 private:
  unsigned int generation_ = 0;
  bool was_[FACT_RULE_COUNT] = {};
  bool spent_[FACT_RULE_COUNT] = {};
};
