// Scene "main": graph of "part-a" (object 1)
class FlowGraphScript_0_1 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    // Live Debugger: nothing in this graph advances while the game is
    // stopped at a breakpoint (the loop's own pause covers the rest).
    if (livedbg::halted()) return;
    // Live Logic: while the editor has a patch for this graph, the
    // interpreter runs it instead of this compiled copy.
    if (livelogic::patched(0, 1)) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
      once2 = false;
      near1 = false;
    }
    frame++;
    if (livedbg::forced(0)) {  // Live Debugger: fired from the editor
      livedbg::hit(0);
      livedbg::hit(1);
      if (!once2) {
        once2 = true;
        livedbg::hit(2);
        {  // Sequence output 1
          livedbg::hit(3);
          factWrite(0, (float)lroundf(factNum[0] + (1.0F)), 3);  // "world.generator.parts"
        }
        {  // Sequence output 2
          livedbg::hit(4);
          ctx.objects[1].visible = false;
        }
      }
    }
    {
      const float dx = ctx.playerPosition.x - ctx.objects[1].data.position[0];
      const float dz = ctx.playerPosition.z - ctx.objects[1].data.position[2];
      const bool isNear = dx * dx + dz * dz < 6.25F;
      if (isNear && !near1) {
      livedbg::hit(0);
      livedbg::hit(1);
      if (!once2) {
        once2 = true;
        livedbg::hit(2);
        {  // Sequence output 1
          livedbg::hit(3);
          factWrite(0, (float)lroundf(factNum[0] + (1.0F)), 3);  // "world.generator.parts"
        }
        {  // Sequence output 2
          livedbg::hit(4);
          ctx.objects[1].visible = false;
        }
      }
      }
      near1 = isNear;
    }
  }

 public:
  // Time machine (docs/time-machine.md): this graph's own
  // state - armed Delays, edge latches, latched outputs.
  FlowGraphScript_0_1() { g_time_FlowGraphScript_0_1 = this; }
  static const unsigned int kTimeBytes = 7;
  void timeCapture(unsigned char* p) const {
    memcpy(p + 0, &frame, 4);
    p[4] = started ? 1 : 0;
    p[5] = once2 ? 1 : 0;
    p[6] = near1 ? 1 : 0;
  }
  void timeRestore(const unsigned char* p) {
    memcpy(&frame, p + 0, 4);
    started = p[4] != 0;
    once2 = p[5] != 0;
    near1 = p[6] != 0;
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
  bool once2 = false;
  bool near1 = false;
};
