// Time machine (docs/time-machine.md): the flow variables and the event bus, both directions.
int flowTimeVarCount() { return 11; }
void flowTimeRead(int index, float* out3) {
  out3[0] = out3[1] = out3[2] = 0.0F;
  switch (index) {
    case 0:
      out3[0] = flowEvtCur[0] ? 1.0F : 0.0F; out3[1] = flowEvtCurVal[0];
      break;  // event "power-on" (delivered)
    case 1:
      out3[0] = flowEvtNext[0] ? 1.0F : 0.0F; out3[1] = flowEvtNextVal[0];
      break;  // event "power-on" (in flight)
    case 2: out3[0] = factNum[0]; break;
    case 3: out3[0] = factNum[1]; break;
    case 4: out3[0] = factNum[2]; break;
    case 5: out3[0] = factNum[3]; break;
    case 6: out3[0] = factNum[4]; break;
    case 7: out3[0] = factNum[5]; break;
    case 8: out3[0] = factNum[6]; break;
    case 9: out3[0] = factNum[7]; break;
    case 10:
      out3[0] = factPos[0][0]; out3[1] = factPos[0][1]; out3[2] = factPos[0][2];
      break;
    default: break;
  }
}
void flowTimeWrite(int index, const float* in3) {
  switch (index) {
    case 0:
      flowEvtCur[0] = in3[0] != 0.0F ? 1 : 0; flowEvtCurVal[0] = in3[1];
      break;  // event "power-on" (delivered)
    case 1:
      flowEvtNext[0] = in3[0] != 0.0F ? 1 : 0; flowEvtNextVal[0] = in3[1];
      break;  // event "power-on" (in flight)
    case 2: factNum[0] = in3[0]; break;
    case 3: factNum[1] = in3[0]; break;
    case 4: factNum[2] = in3[0]; break;
    case 5: factNum[3] = in3[0]; break;
    case 6: factNum[4] = in3[0]; break;
    case 7: factNum[5] = in3[0]; break;
    case 8: factNum[6] = in3[0]; break;
    case 9: factNum[7] = in3[0]; break;
    case 10:
      factPos[0][0] = in3[0]; factPos[0][1] = in3[1]; factPos[0][2] = in3[2];
      break;
    default: break;
  }
}

// Live Logic (docs/live-logic.md): flow-variable access for the
// interpreter - patched graphs read and write the very same arrays the
// compiled ones do, so a hot-patched graph shares state with the rest.
void flowLiveSetVarInt(int index, int value) {
  (void)index; (void)value;
}
void flowLiveSetVarBool(int index, bool value) {
  (void)index; (void)value;
}
void flowLiveSetVarPos(int index, const float* v3) {
  (void)index; (void)v3;
}
int flowLiveGetVarInt(int index) {
  (void)index;
  return 0;
}
bool flowLiveGetVarBool(int index) {
  (void)index;
  return false;
}
void flowLiveGetVarPos(int index, float* out3) {
  (void)index; (void)out3;
}

